// Generated once by `i18next-cli types`, then adjusted by hand: our language
// files hold the default namespace ("translation") directly, so the Swedish
// (source) resources are mapped onto it. resources.d.ts is regenerated by
// `npm run i18n:extract` (or `i18n:types`); don't edit that one.
import type Resources from "./resources";

declare module "i18next" {
  interface CustomTypeOptions {
    enableSelector: false;
    defaultNS: "translation";
    resources: { translation: Resources["sv"] };
  }
}
